import{_ as e,o,c as i,a3 as r}from"./chunks/framework.BwzYn71E.js";const m=JSON.parse('{"title":"Summary: Equations and Conditions for the Basic Control Structures","description":"","frontmatter":{"translationSource":{"title":"小结 基本控制结构的表达式和条件","archivedAt":"2026-11-23","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=3RF1vkSJAHUemy8DSi9Qpu","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/basic-control-structures-summary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/basic-control-structures-summary"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/basic-control-structures-summary"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/basic-control-structures-summary"}]]},"headers":[],"relativePath":"basic-control-structures-summary.md","filePath":"logistics/src/page-3RF1vkSJAHUemy8DSi9Qpu.md"}'),a={name:"basic-control-structures-summary.md"};function n(l,t,s,u,p,c){return o(),i("div",null,[...t[0]||(t[0]=[r('<div class="logistics-content"><h1 id="summary-equations-and-conditions-for-the-basic-control-structures" tabindex="-1">Summary: Equations and Conditions for the Basic Control Structures <a class="header-anchor" href="#summary-equations-and-conditions-for-the-basic-control-structures" aria-label="Permalink to &quot;Summary: Equations and Conditions for the Basic Control Structures&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>Content updated: </span><a href="/endfield-skydoc/changelog/capture-2026-11-23T06-44-45-722Z-4358a738" title="Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record." aria-label="Content updated: 2026-11-23. Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record."><time datetime="2026-11-23T06:44:47.018Z">2026-11-23</time></a><span class="page-updated-zone"> (China Standard Time)</span></p><blockquote><p>Source page ID: <code>3RF1vkSJAHUemy8DSi9Qpu</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=3RF1vkSJAHUemy8DSi9Qpu" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Read each equals sign as “is determined by.”</p><ul><li><p>Simple structure: upstream input → machine → downstream output</p><ul><li><p>Direct control: downstream output = upstream input. Condition: both sides are flowing.</p></li><li><p>Blocking control: upstream input = downstream output. Condition: both sides are blocked.</p></li></ul></li><li><p>Splitter structure: upstream input → splitter → machine 1/2 → downstream output 1</p><ul><li><p>Direct control: downstream output 1/2 = upstream input × split ratio. Condition: all branches are flowing.</p></li><li><p>Full blocking control: upstream input = downstream output 1 + downstream output 2. Condition: all branches are blocked.</p></li><li><p>Blocking control: flowing downstream output = flowing upstream input − blocked downstream output. Condition: one downstream branch is blocked and the other is flowing.</p></li></ul></li><li><p>Converger structure: upstream input 1/2 → converger → machine → downstream output</p><ul><li><p>Direct control: downstream output = upstream input 1 + upstream input 2. Condition: all branches are flowing.</p></li><li><p>Full blocking control: upstream input 1/2 = downstream output × merge ratio. Condition: all branches are blocked.</p></li><li><p>Blocking control: blocked upstream input = blocked downstream output − flowing upstream input. Condition: one upstream branch is blocked and the other is flowing.</p></li></ul></li><li><p>Multi-input machine: upstream input 1/2 → machine → downstream output</p><ul><li><p>Direct control: downstream output = upstream input 1/2 × recipe ratio. Condition: all branches are flowing.</p></li><li><p>Full blocking control: upstream input 1/2 = downstream output / recipe ratio. Condition: all branches are blocked.</p></li><li><p>Blocking control: blocked upstream input = flowing upstream input × recipe ratio 1 / recipe ratio 2. Condition: one upstream branch is blocked and the other is flowing.</p></li></ul></li></ul></div>',1)])])}const h=e(a,[["render",n]]);export{m as __pageData,h as default};
